fn parse_opencode_auth(output: &std::process::Output) -> Option<bool> {
    let text = String::from_utf8_lossy(&output.stdout);
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return output.status.success().then_some(false);
    }
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(trimmed) {
        return Some(json_has_entries(&value));
    }
    let lower = trimmed.to_lowercase();
    if lower.contains("no credentials") || lower.contains("not logged in") {
        return Some(false);
    }
    None
}

fn json_has_entries(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Array(items) => !items.is_empty(),
        serde_json::Value::Object(entries) => !entries.is_empty(),
        _ => false,
    }
}

input.new_string:
fn parse_opencode_auth(output: &std::process::Output) -> Option<bool> {
    let text = String::from_utf8_lossy(&output.stdout);
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return output.status.success().then_some(false);
    }
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(trimmed) {
        return Some(opencode_has_usable_auth(&value));
    }
    let lower = trimmed.to_lowercase();
    if lower.contains("no credentials") || lower.contains("not logged in") {
        return Some(false);
    }
    None
}

/// `opencode auth list --format json` entries. A connection with
/// `status.status == "needs_auth"` (e.g. "Reconnect OpenCode Console") does not
/// count — ACP still returns "Authentication required" for those.
fn opencode_has_usable_auth(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Array(items) => items.iter().any(opencode_provider_usable),
        serde_json::Value::Object(entries) => !entries.is_empty(),
        _ => false,
    }
}

fn opencode_provider_usable(provider: &serde_json::Value) -> bool {
    let Some(connections) = provider.get("connections").and_then(|c| c.as_array()) else {
        // Older list shapes used a bare provider id with no connections array.
        return provider.get("id").or_else(|| provider.get("provider")).is_some();
    };
    connections.iter().any(|connection| {
        connection
            .get("status")
            .and_then(|status| status.get("status"))
            .and_then(|status| status.as_str())
            != Some("needs_auth")
    })
}

