    const w = mount(ProjectSetupPrompt, { props: { projectId: "bare" } });
    await w.get("[data-testid='project-setup-confirm']").trigger("click");
    await flushPromises();
    expect(h.toastError).toHaveBeenCalledWith("disk full");
  });
});

